const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '*DeviceConfig*' -g 'package.json' -g 'vitest.config.*' -g 'jest.config.*' -g 'checkpoint.md'",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"git status --short",workdir:"/app",max_output_tokens:1000})
]); for (const x of r) text(x);

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -iname '*DeviceConfig*' -o -name package.json -o -name 'vitest.config.*' -o -name 'jest.config.*' | head -80",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"find .codex-role-output -maxdepth 2 -type f 2>/dev/null",workdir:"/app",max_output_tokens:1000})
]); for (const x of r) text(x);

const r = await Promise.allSettled([
  tools.exec_command({cmd:"cat test/client/misc/DeviceConfigTest.ts",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"cat src/misc/DeviceConfig.ts",workdir:"/app",max_output_tokens:12000}),
  tools.exec_command({cmd:"cat package.json",workdir:"/app",max_output_tokens:4000}),
  tools.exec_command({cmd:"find . -name AGENTS.md -not -path './node_modules/*' -print",workdir:"/app",max_output_tokens:1000})
]); for (const x of r) text(x);

