import {client} from "./ClientDetector"
import type {Base64} from "@tutao/tutanota-utils"
import {base64ToUint8Array, uint8ArrayToBase64} from "@tutao/tutanota-utils"
import type {LanguageCode} from "./LanguageViewModel"
import type {ThemeId} from "../gui/theme"
import type {CalendarViewType} from "../calendar/view/CalendarViewModel"
import type {CredentialsStorage, PersistentCredentials} from "./credentials/CredentialsProvider"
import type {CredentialEncryptionMode} from "./credentials/CredentialEncryptionMode"
import {assertMainOrNodeBoot} from "../api/common/Env"
import {PersistedAssignmentData, UsageTestStorage} from "./UsageTestModel"

assertMainOrNodeBoot()
export const defaultThemeId: ThemeId = "light"

type ConfigStorage = Pick<Storage, "getItem" | "setItem">

type Config = {
	_version: number
	_credentials: Map<Id, PersistentCredentials>
	_scheduledAlarmUsers: Id[]
	_themeId: ThemeId
	_language: LanguageCode | null
	_defaultCalendarView: Record<Id, CalendarViewType | null>
	_hiddenCalendars: Record<Id, Id[]>
	_signupToken: string
	_credentialEncryptionMode: CredentialEncryptionMode | null
	_encryptedCredentialsKey: Base64 | null
	_testDeviceId: string | null
	_testAssignments: PersistedAssignmentData | null
}

function availableStorage(): ConfigStorage | null {
	return client.localStorage() ? localStorage : null
}

/**
 * Device config for internal user auto login. Only one config per device is stored.
 */
export class DeviceConfig implements CredentialsStorage, UsageTestStorage {
	static readonly Version = 3
	static readonly LocalStorageKey = "tutanotaConfig"

	private config: Config
	private lastStoredConfig: string | null = null

	constructor(
		private readonly version: number = DeviceConfig.Version,
		private readonly storage: ConfigStorage | null = availableStorage(),
		private readonly storageKey: string = DeviceConfig.LocalStorageKey,
	) {
		this.config = this.defaultConfig()
		this._load()
	}

	private defaultConfig(): Config {
		return {
			_version: this.version,
			_credentials: new Map(),
			_scheduledAlarmUsers: [],
			_themeId: defaultThemeId,
			_language: null,
			_defaultCalendarView: {},
			_hiddenCalendars: {},
			_signupToken: "",
			_credentialEncryptionMode: null,
			_encryptedCredentialsKey: null,
			_testDeviceId: null,
			_testAssignments: null,
		}
	}

	store(persistentCredentials: PersistentCredentials): void {

		const existing = this.config._credentials.get(persistentCredentials.credentialInfo.userId)

		if (existing?.databaseKey) {
			persistentCredentials.databaseKey = existing.databaseKey
		}

		this.config._credentials.set(persistentCredentials.credentialInfo.userId, persistentCredentials)

		this._writeToStorage()
	}

	loadByUserId(userId: Id): PersistentCredentials | null {
		return this.config._credentials.get(userId) ?? null
	}

	loadAll(): Array<PersistentCredentials> {
		return Array.from(this.config._credentials.values())
	}

	deleteByUserId(userId: Id): void {
		this.config._credentials.delete(userId)

		this._writeToStorage()
	}

	_load(): void {
		let loadedConfig: any | null = null
		try {
			const loadedConfigString = this.storage?.getItem(this.storageKey)
			loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		} catch (e) {
			console.warn("Could not load device config", e)
		}

		const migrated = loadedConfig != null && migrateConfig(loadedConfig, this.version)
		const defaults = this.defaultConfig()
		this.config = loadedConfig == null ? defaults : {
			_version: typeof loadedConfig._version === "number" ? loadedConfig._version : defaults._version,
			_credentials: deserializeCredentials(loadedConfig._credentials),
			_scheduledAlarmUsers: Array.isArray(loadedConfig._scheduledAlarmUsers) ? loadedConfig._scheduledAlarmUsers : defaults._scheduledAlarmUsers,
			_themeId: loadedConfig._themeId ?? defaults._themeId,
			_language: loadedConfig._language ?? defaults._language,
			_defaultCalendarView: loadedConfig._defaultCalendarView ?? defaults._defaultCalendarView,
			_hiddenCalendars: loadedConfig._hiddenCalendars ?? defaults._hiddenCalendars,
			_signupToken: loadedConfig._signupToken ?? defaults._signupToken,
			_credentialEncryptionMode: loadedConfig._credentialEncryptionMode ?? defaults._credentialEncryptionMode,
			_encryptedCredentialsKey: loadedConfig._encryptedCredentialsKey ?? defaults._encryptedCredentialsKey,
			_testDeviceId: loadedConfig._testDeviceId ?? defaults._testDeviceId,
			_testAssignments: loadedConfig._testAssignments ?? defaults._testAssignments,
		}

		const missingSignupToken = !this.config._signupToken
		if (missingSignupToken) {
			this.config._signupToken = createSignupToken()
		}

		if (migrated || missingSignupToken) {
			this._writeToStorage()
		} else {
			// Loading an existing config must not rewrite it. Keep a semantic snapshot
			// so subsequent no-op setters also leave storage untouched.
			this.lastStoredConfig = this.serializeConfig()
		}
	}

	_parseConfig(loadedConfigString: string): any | null {
		try {
			const parsed = JSON.parse(loadedConfigString)
			return parsed != null && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null
		} catch (e) {
			console.warn("Could not parse device config")
			return null
		}
	}

	getSignupToken(): string {
		return this.config._signupToken
	}

	hasScheduledAlarmsForUser(userId: Id): boolean {
		return this.config._scheduledAlarmUsers.includes(userId)
	}

	setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this.config._scheduledAlarmUsers.indexOf(userId)

		const scheduledSaved = scheduledIndex !== -1

		if (setScheduled && !scheduledSaved) {
			this.config._scheduledAlarmUsers.push(userId)
		} else if (!setScheduled && scheduledSaved) {
			this.config._scheduledAlarmUsers.splice(scheduledIndex, 1)
		}

		this._writeToStorage()
	}

	setNoAlarmsScheduled() {
		this.config._scheduledAlarmUsers = []

		this._writeToStorage()
	}

	getLanguage(): LanguageCode | null {
		return this.config._language
	}

	setLanguage(language: LanguageCode | null) {
		this.config._language = language

		this._writeToStorage()
	}

	private serializeConfig(): string {
		return JSON.stringify(this.config, (key, value) => {
			return key === "_credentials" ? Object.fromEntries(this.config._credentials) : value
		})
	}

	_writeToStorage() {
		const serialized = this.serializeConfig()
		if (serialized === this.lastStoredConfig || this.storage == null) {
			return
		}

		try {
			this.storage.setItem(this.storageKey, serialized)
			this.lastStoredConfig = serialized
		} catch (e) {
